// ==== public/js/day-fuel-controller.js ====
(() => {
// @ts-check
// Plan -> Food day-fuel load/edit controller.
(() => {
    const DAY_FUEL_ASK = "How's my eating shaping up today, and does it fit my goal?";
    function fuelRoot(options = {}) {
        return options.root || view;
    }
    function fuelStillCurrent(token, root, options) {
        if (options.isCurrent)
            return options.isCurrent(token);
        return Boolean(root.querySelector("#dayFuelSlot"));
    }
    function fuelNumberOrNull(value) {
        const text = String(value ?? "").trim();
        if (!text)
            return null;
        const numeric = Number(text);
        return Number.isFinite(numeric) ? numeric : null;
    }
    function fuelInputValue(el, selector) {
        return el.querySelector(selector)?.value || "";
    }
    function fuelMealOptions(entry) {
        return ["breakfast", "lunch", "dinner", "snack", "meal"].map((meal) => {
            const selected = String(entry.meal || "").toLowerCase() === meal ? "selected" : "";
            return `<option value="${meal}" ${selected}>${CairnDayFuel.MEAL_LABEL[meal]}</option>`;
        }).join("");
    }
    async function loadDayFuel(token, options = {}) {
        const root = fuelRoot(options);
        const slot = root.querySelector("#dayFuelSlot");
        if (!slot)
            return;
        const qs = state.logDate ? `?date=${encodeURIComponent(state.logDate)}` : "";
        let response = null;
        try {
            response = await api("/nutrition/day" + qs);
        }
        catch {
            slot.innerHTML = "";
            return;
        }
        if (!fuelStillCurrent(token, root, options))
            return;
        if (!response || typeof response !== "object") {
            slot.innerHTML = "";
            return;
        }
        const day = response;
        state._dayFuel = day;
        slot.innerHTML = CairnDayFuel.dayFuelHtml(day);
        runCountUps(slot);
        slot.querySelectorAll("[data-fooditem]").forEach((row) => row.addEventListener("click", () => openFoodEdit(Number(row.dataset.fooditem), row, options)));
        slot.querySelector("#dayFuelAsk")?.addEventListener("click", () => {
            if (options.onAsk)
                options.onAsk();
            else
                gotoChatWith(DAY_FUEL_ASK);
        });
    }
    function openFoodEdit(id, fromEl, options = {}) {
        const day = state._dayFuel;
        const entry = day && Array.isArray(day.entries) ? day.entries.find((item) => item.id === id) : null;
        if (!entry)
            return;
        openDetailFrom(fromEl, () => {
            const el = mountDetail(`
        <h2 class="detail-title">Edit this meal</h2>
        <div class="detail-ctx lbl">correct what was logged &middot; macros are rough &mdash; fix anything off</div>
        <div class="field"><label>Description</label>
          <input id="fedSummary" type="text" value="${escAttr(entry.summary || "")}" maxlength="200"></div>
        <div class="field"><label>Meal</label>
          <select id="fedMeal">${fuelMealOptions(entry)}</select></div>
        <div class="fed-macros">
          <div class="field"><label>kcal</label><input id="fedKcal" type="number" inputmode="numeric" value="${entry.kcal ?? ""}"></div>
          <div class="field"><label>protein (g)</label><input id="fedProtein" type="number" inputmode="numeric" value="${entry.protein_g ?? ""}"></div>
          <div class="field"><label>carbs (g)</label><input id="fedCarbs" type="number" inputmode="numeric" value="${entry.carbs_g ?? ""}"></div>
          <div class="field"><label>fat (g)</label><input id="fedFat" type="number" inputmode="numeric" value="${entry.fat_g ?? ""}"></div>
        </div>
        <div class="detail-actions">
          <button class="pillbtn pill-accent" id="fedSave">Save</button>
          <button class="pillbtn" data-close>Close</button>
          <button class="pillbtn" id="fedDel">Delete</button>
        </div>`);
            wireDetailCommon();
            el.querySelector("#fedSave")?.addEventListener("click", async () => {
                const meal = el.querySelector("#fedMeal");
                const body = {
                    summary: fuelInputValue(el, "#fedSummary").trim(),
                    meal: meal?.value || "meal",
                    kcal: fuelNumberOrNull(fuelInputValue(el, "#fedKcal")),
                    protein_g: fuelNumberOrNull(fuelInputValue(el, "#fedProtein")),
                    carbs_g: fuelNumberOrNull(fuelInputValue(el, "#fedCarbs")),
                    fat_g: fuelNumberOrNull(fuelInputValue(el, "#fedFat")),
                };
                try {
                    await api(`/food-notes/${id}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
                    toast("Updated");
                }
                catch {
                    toast("Couldn't save");
                    return;
                }
                swrInvalidate("progress:energy");
                closeDetail(true);
                options.onRerender?.();
            });
            const del = el.querySelector("#fedDel");
            if (del)
                del.addEventListener("click", () => armDelete(del, async () => {
                    try {
                        await api(`/food-notes/${id}`, { method: "DELETE" });
                        toast("Removed");
                    }
                    catch {
                        toast("Couldn't remove");
                        return;
                    }
                    swrInvalidate("progress:energy");
                    closeDetail(true);
                    options.onRerender?.();
                }));
        });
    }
    const CAIRN_DAY_FUEL_CONTROLLER = {
        loadDayFuel,
        openFoodEdit,
    };
    Object.assign(globalThis, { CairnDayFuelController: CAIRN_DAY_FUEL_CONTROLLER });
    if (typeof window !== "undefined")
        window.CairnDayFuelController = CAIRN_DAY_FUEL_CONTROLLER;
})();
})();
;
// ==== public/js/meal-row-client.js ====
(() => {
// @ts-check
// Meal row/day render primitives for Plan -> Meals.
(() => {
    const MEAL_HINT_CHIPS = ["Fish", "Chicken", "Beef", "Veggie", "Lighter", "Bigger", "Quick to make"];
    function mealRecord(value) {
        return value && typeof value === "object" ? value : {};
    }
    function mealItemsText(value) {
        return Array.isArray(value) ? value.join(", ") : String(value || "");
    }
    function mealSlotFor(name, index) {
        const normalized = String(name || "").toLowerCase();
        for (const slot of ["breakfast", "lunch", "dinner", "snack"]) {
            if (normalized.includes(slot))
                return slot;
        }
        return ["breakfast", "lunch", "dinner"][Number(index)] || "snack";
    }
    function todayNameFor(now) {
        const dayNames = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
        const candidate = now && typeof now === "object" && typeof now.getDay === "function"
            ? Number(now.getDay())
            : new Date().getDay();
        return dayNames[candidate] || dayNames[new Date().getDay()];
    }
    function mealsCtxFor(plan, now) {
        const p = mealRecord(plan);
        const parsed = mealRecord(p.parsed);
        return {
            weekOf: String(p.week_of || String(p.created_at || "").slice(0, 10)),
            targetKcal: Number(parsed.daily_kcal) || 0,
            todayName: todayNameFor(now),
        };
    }
    function mealRowHtml(meal, mealIndex, options) {
        const x = mealRecord(meal);
        const items = mealItemsText(x.items);
        const query = `${x.name || x.meal || ""} ${items}`.trim();
        const tile = artImg("food", query, "artile-md meal-art", art("food", query));
        const macros = [["P", x.protein_g], ["C", x.carbs_g], ["F", x.fat_g]]
            .filter(([label, value]) => value != null && value !== "" && (label === "P" || Number(value) > 0))
            .map(([label, value]) => `<span class="lbl">${label} ${escHtml(String(value))}</span>`).join("");
        const loggable = typeof mealIndex === "number";
        const planner = loggable && options && typeof options.di === "number";
        const logBtn = loggable ? `<button class="meal-log" data-mlog="${escAttr(JSON.stringify({
            name: x.name || x.meal || "",
            items,
            kcal: x.kcal ?? null,
            protein_g: x.protein_g ?? null,
            carbs_g: x.carbs_g ?? null,
            fat_g: x.fat_g ?? null,
            i: mealIndex,
        }))}">+ Log it</button>` : "";
        const count = Number(options?.count) || 0;
        const tools = planner
            ? `<div class="meal-rowtools">${logBtn}<button class="meal-swapbtn" data-mswap aria-label="Swap this meal">⇄ Swap</button><span class="meal-mvgrp"><button class="meal-mv" data-mv="-1" aria-label="Move up" ${mealIndex === 0 ? "disabled" : ""}>▲</button><button class="meal-mv" data-mv="1" aria-label="Move down" ${mealIndex >= count - 1 ? "disabled" : ""}>▼</button></span></div>`
            : logBtn;
        const row = `<div class="meal-row"${planner ? ` data-di="${options.di}" data-mi="${mealIndex}"` : ""}>
      ${tile}
      <div class="meal-main">
        <div class="meal-name">${escHtml(x.name || x.meal || "")}</div>
        ${items ? `<div class="meal-items">${escHtml(items)}</div>` : ""}
        ${tools}
      </div>
      <div class="meal-macros">
        ${x.kcal ? `<span class="numeral">${escHtml(String(x.kcal))}</span>` : ""}
        ${macros}
      </div>
    </div>`;
        if (!planner)
            return row;
        return row + `<div class="meal-swap" hidden data-di="${options.di}" data-mi="${mealIndex}">
      <input class="meal-swap-hint" type="text" maxlength="140" placeholder="Optional hint — fish, lighter, quick…">
      <div class="meal-swap-chips">${MEAL_HINT_CHIPS.map((hint) => `<button type="button" class="chip hintchip" data-hint="${escAttr(hint)}">${escHtml(hint)}</button>`).join("")}</div>
      <div class="meal-swap-actions">
        <button type="button" class="pillbtn pill-accent meal-swap-go">Swap it</button>
        <button type="button" class="pillbtn meal-swap-cancel">Cancel</button>
      </div>
    </div>`;
    }
    function mealDayHtml(day, dayIndex, context) {
        const d = mealRecord(day);
        const meals = Array.isArray(d.meals) ? d.meals : [];
        const kcal = meals.reduce((total, meal) => total + (Number(mealRecord(meal).kcal) || 0), 0);
        const protein = meals.reduce((total, meal) => total + (Number(mealRecord(meal).protein_g) || 0), 0);
        const todayPrefix = String(context.todayName || "").toLowerCase();
        const isToday = Boolean(todayPrefix) && String(d.day || "").toLowerCase().startsWith(todayPrefix);
        const totals = kcal || protein
            ? `<div class="mealday-total"><span class="numeral" data-cu="${kcal}">0</span><span class="lbl"> cal${protein ? ` · ${protein}g protein` : ""}</span></div>`
            : "";
        const targetKcal = Number(context.targetKcal) || 0;
        const bar = kcal && targetKcal
            ? `<div class="mealday-bar"><div class="mealday-bar-fill barfill" style="width:${Math.min(100, Math.round((kcal / targetKcal) * 100))}%"></div></div>`
            : "";
        return `<section class="mealday${isToday ? " mealday-today" : ""} reveal" style="${stagger(dayIndex + 2)}" data-mday="${dayIndex}">
      <div class="mealday-head">
        <div><div class="lbl">${isToday ? `<span class="mealday-now">Today</span> · ` : ""}${escHtml(context.weekOf)}</div><h2 class="mealday-name">${escHtml(d.day || `Day ${dayIndex + 1}`)}</h2></div>
        ${totals}
      </div>
      ${bar}
      <div class="mealday-card">${meals.map((meal, mealIndex) => mealRowHtml(meal, mealIndex, { di: dayIndex, count: meals.length })).join("") || `<div class="empty">No meals</div>`}</div>
      ${d.note ? `<div class="mealday-note">${escHtml(d.note)}</div>` : ""}
    </section>`;
    }
    const CAIRN_MEAL_ROWS = {
        MEAL_HINT_CHIPS,
        record: mealRecord,
        itemsText: mealItemsText,
        mealSlotFor,
        todayNameFor,
        mealsCtxFor,
        mealRowHtml,
        mealDayHtml,
    };
    Object.assign(globalThis, {
        CairnMealRows: CAIRN_MEAL_ROWS,
        mealSlotFor,
        mealRowHtml,
        mealDayHtml,
    });
    if (typeof window !== "undefined") {
        Object.assign(window, {
            CairnMealRows: CAIRN_MEAL_ROWS,
            mealSlotFor,
            mealRowHtml,
            mealDayHtml,
        });
    }
})();
})();
;
